#!/usr/bin/env node
// inputs start from argv[2]
const vals = process.argv.slice(2);
process.stdout.write(vals.join(' ') + '\n');

#!/usr/bin/env node
const sdk = require('./lyenv_sdk.js');

async function main() {
  await sdk.read_request();
  sdk.log('sdk_js_ok');
  sdk.respond_ok('');
}

main().catch((err) => {
  try { sdk.respond_error(err.message || String(err)); }
  catch { process.stderr.write(String(err) + '\n'); process.exit(1); }
});
